def is_product_of_squares(n):
    if n < 0:
        return False

    factors = {}
    i = 2
    while i * i <= n:
        count = 0
        while n % i == 0:
            count += 1
            n //= i
        if count % 2 != 0:
            return False
        i += 1

    if n > 1:
        return True if factors.get(n) and factors[n] % 2 == 0 else False

    return True
```

